<?php
require_once __DIR__ . '/../config/database.php'; require_once __DIR__ . '/../config/config.php'; checkSession();
if ($_SESSION['user_role'] !== ROLE_CONTADOR) { header('Location: '.BASE_URL.'/index.php'); exit(); }
if (empty($_SESSION['csrf_finanzas'])) $_SESSION['csrf_finanzas']=bin2hex(random_bytes(32));
$tab=$_GET['tab']??'facturas'; $msg=''; $err='';
if ($_SERVER['REQUEST_METHOD']==='POST') { if(!hash_equals($_SESSION['csrf_finanzas'],$_POST['csrf']??'')) $err='La solicitud expiró.'; else try { $a=$_POST['action']??''; if($a==='factura'){executeQuery("UPDATE facturacion SET estado_factura=? WHERE id_factura=?",[$_POST['estado'],(int)$_POST['id']]);$msg='Estado de factura actualizado.';} elseif($a==='pago'){executeQuery("UPDATE historial_facturacion SET estado_pago=? WHERE id_historial_factura=?",[$_POST['estado'],(int)$_POST['id']]);$msg='Estado de pago actualizado.';} elseif($a==='nomina'){ $id=(int)$_POST['id'];$periodo=$_POST['periodo'];$exist=getRecord('SELECT id_pago_nomina FROM pagos_nomina WHERE id_empleado_nomina=? AND periodo=?',[$id,$periodo]); if(!$exist) executeQuery("INSERT INTO pagos_nomina(id_empleado_nomina,periodo,monto,metodo_pago,estado_pago,fecha_pago,id_usuario_registra) SELECT id_empleado_nomina,?,salario_base,?,'pagado',CURDATE(),? FROM empleados_nomina WHERE id_empleado_nomina=?",[$periodo,$_POST['metodo'],(int)$_SESSION['user_id'],$id]); else executeQuery("UPDATE pagos_nomina SET estado_pago='pagado',fecha_pago=CURDATE(),metodo_pago=?,id_usuario_registra=? WHERE id_pago_nomina=?",[$_POST['metodo'],(int)$_SESSION['user_id'],$exist['id_pago_nomina']]);$msg='Pago de nómina registrado.';} }catch(Throwable $e){$err='No fue posible completar la operación.';} }
include __DIR__.'/../includes/header.php'; $periodo=$_GET['periodo']??date('Y-m');
?>
<div class="page-header"><div><h1>Gestión financiera</h1><p>Facturas, pagos de clientes y nómina de empleados.</p></div></div>
<div class="quick-actions"><a class="action-btn" href="?tab=facturas">Facturas</a><a class="action-btn" href="?tab=pagos">Pagos</a><a class="action-btn" href="?tab=nomina">Nómina</a></div>
<?php if($msg):?><div class="alert alert-success"><?=displayText($msg)?></div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?=displayText($err)?></div><?php endif;?>
<section class="content-section mt-20"><div class="table-responsive"><table class="table"><thead><?php if($tab==='facturas'):?><tr><th>Factura</th><th>Paciente</th><th>Total</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach(getRecords("SELECT f.id_factura,f.numero_factura,CONCAT(p.nombre,' ',p.apellido) paciente,f.total,f.estado_factura FROM facturacion f JOIN pacientes p ON p.id_paciente=f.id_paciente ORDER BY f.fecha_factura DESC") as $r):?><tr><td><?=displayText($r['numero_factura'])?></td><td><?=displayText($r['paciente'])?></td><td>$<?=number_format($r['total'],2)?></td><td><?=displayText($r['estado_factura'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['csrf_finanzas'])?>"><input type="hidden" name="action" value="factura"><input type="hidden" name="id" value="<?=$r['id_factura']?>"><select name="estado"><option>pendiente</option><option>pagada</option><option>anulada</option></select><button class="btn btn-sm btn-primary">Actualizar</button> <a class="btn btn-sm btn-secondary" target="_blank" href="factura_imprimir.php?id=<?=$r['id_factura']?>">Comprobante</a></form></td></tr><?php endforeach;?><?php elseif($tab==='pagos'):?><tr><th>Factura</th><th>Monto</th><th>Fecha</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach(getRecords("SELECT h.id_historial_factura,f.numero_factura,h.monto_pago,h.fecha_pago,h.estado_pago FROM historial_facturacion h JOIN facturacion f ON f.id_factura=h.id_factura ORDER BY h.fecha_pago DESC") as $r):?><tr><td><?=displayText($r['numero_factura'])?></td><td>$<?=number_format($r['monto_pago'],2)?></td><td><?=displayText($r['fecha_pago'])?></td><td><?=displayText($r['estado_pago'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['csrf_finanzas'])?>"><input type="hidden" name="action" value="pago"><input type="hidden" name="id" value="<?=$r['id_historial_factura']?>"><select name="estado"><option>confirmado</option><option>pendiente</option><option>rechazado</option></select><button class="btn btn-sm btn-primary">Actualizar</button></form></td></tr><?php endforeach;?><?php else:?><tr><th>Empleado</th><th>Cargo</th><th>Salario base</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach(getRecords("SELECT e.id_empleado_nomina,u.nombre,u.apellido,r.nombre_rol,e.salario_base,COALESCE(p.estado_pago,'pendiente') estado,p.id_pago_nomina FROM empleados_nomina e JOIN usuarios u ON u.id_usuario=e.id_usuario JOIN roles r ON r.id_rol=u.id_rol LEFT JOIN pagos_nomina p ON p.id_empleado_nomina=e.id_empleado_nomina AND p.periodo=? WHERE e.estado='activo'",[$periodo]) as $r):?><tr><td><?=displayText($r['nombre'].' '.$r['apellido'])?></td><td><?=displayText($r['nombre_rol'])?></td><td>$<?=number_format($r['salario_base'],2)?></td><td><?=displayText($r['estado'])?></td><td><?php if($r['estado']!=='pagado'):?><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['csrf_finanzas'])?>"><input type="hidden" name="action" value="nomina"><input type="hidden" name="id" value="<?=$r['id_empleado_nomina']?>"><input type="hidden" name="periodo" value="<?=htmlspecialchars($periodo)?>"><select name="metodo"><option>transferencia</option><option>efectivo</option><option>cheque</option></select><button class="btn btn-sm btn-primary">Pagar</button></form><?php else:?><a class="btn btn-sm btn-secondary" target="_blank" href="comprobante_nomina.php?id=<?=$r['id_pago_nomina']?>">Comprobante</a><?php endif;?></td></tr><?php endforeach;?><?php endif;?></tbody></table></div></section>
